mapper.sql:
WHERE user_id = #{userId}
  AND deleted_at IS NULL

    AND (display_term LIKE CONCAT('%', #{keyword}, '%')
         OR normalized_term LIKE CONCAT('%', #{keyword}, '%'))


    AND status = #{status}


    AND EXISTS (
        SELECT 1
        FROM vocabulary_card_source source
        WHERE source.card_uid = vocabulary_card.card_uid
          AND source.user_id = #{userId}
          AND source.source_type = #{sourceType}
    )

mapper.select:
SELECT 
FROM vocabulary_card
WHERE user_id = #{userId}
  AND language = #{language}
  AND normalized_term = #{normalizedTerm}
LIMIT 1

mapper.insert:
INSERT INTO vocabulary_card (
    card_uid, user_id, language, original_term, normalized_term, display_term,
    template_key, template_version, status, active_revision_uid, last_captured_at, deleted_at
) VALUES (
    #{cardUid}, #{userId}, #{language}, #{originalTerm}, #{normalizedTerm}, #{displayTerm},
    #{templateKey}, #{templateVersion}, #{status}, #{activeRevisionUid}, #{lastCapturedAt}, #{deletedAt}
)

mapper.select:
SELECT 
FROM vocabulary_card
WHERE user_id = #{userId}
  AND card_uid = #{cardUid}
  AND deleted_at IS NULL
LIMIT 1

mapper.update:
UPDATE vocabulary_card
SET deleted_at = CURRENT_TIMESTAMP,
    updated_at = CURRENT_TIMESTAMP
WHERE user_id = #{userId}
  AND card_uid = #{cardUid}
  AND deleted_at IS NULL
